			assertTrue(store.getBackingStore().awaitFrontierStatisticsReady(TimeUnit.SECONDS.toMillis(30)));
			var vf = SimpleValueFactory.getInstance();
			try (SailConnection seed = store.getConnection()) {
				seed.begin(IsolationLevels.SNAPSHOT);
				seed.addStatement(vf.createIRI("urn:postcommit:s"), vf.createIRI("urn:postcommit:p"),
						vf.createLiteral("v"));
				seed.commit();
			}
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());
			TripleStore triples = store.getBackingStore().getTripleStore();
